/* ROUND 5 FIX: the region I/O helper is created through the portable thread
 * layer (source/platform/thread.h) rather than raw LWP_CreateThread/
 * pthread_create, so a failure to spawn it is counted by
 * thread_create_failure_count() -- the counter the Wii hang report already
 * dumps -- instead of being visible only as "the async path never armed".
 * thread.h also pulls in <ogc/cond.h> on the Wii, which is where cond_t
 * lives (gccore.h stops at mutex_t). */
